        var maxGap = 0.0
        for i in 1..<input.count { maxGap = max(maxGap, input[i].t - input[i - 1].t) }

        let count = Int(((last.t - first.t) * rate).rounded(.down)) + 1
        var out: [MotionSample] = []
        out.reserveCapacity(count)
        var j = 0
