import Foundation

/// Dependent multivariate DTW with a Sakoe–Chiba band and early abandoning (D10).
public enum DTW {
    /// Normalized distance (total path cost / (n + m)). Returns `.infinity` once it can no
    /// longer beat `cutoff`, which skips most of the work for hopeless references.
    public static func distance(_ a: FeatureSequence, _ b: FeatureSequence,
                                band bandFraction: Double = 0.2, cutoff: Double = .infinity) -> Double {
        let n = a.count, m = b.count, dims = a.dims
        guard n > 0, m > 0, dims == b.dims else { return .infinity }
        let band = max(abs(n - m), Int(Double(max(n, m)) * bandFraction))
        let limit = cutoff.isFinite ? cutoff * Double(n + m) : .infinity

        var previous = [Double](repeating: .infinity, count: m + 1)
        var current = previous
        previous[0] = 0

        return a.values.withUnsafeBufferPointer { av in
            b.values.withUnsafeBufferPointer { bv in
                for i in 1...n {
                    for j in 0...m { current[j] = .infinity }
                    let lo = max(1, i - band), hi = min(m, i + band)
                    var rowMin = Double.infinity
                    if lo <= hi {
                        let ai = (i - 1) * dims
                        for j in lo...hi {
                            let bj = (j - 1) * dims
                            var sum = 0.0
                            for d in 0..<dims { let diff = av[ai + d] - bv[bj + d]; sum += diff * diff }
                            let best = min(previous[j], current[j - 1], previous[j - 1])
                            let value = sum.squareRoot() + best
                            current[j] = value
                            if value < rowMin { rowMin = value }
                        }
                    }
                    if rowMin > limit { return .infinity }
                    swap(&previous, &current)
                }
                return previous[m] / Double(n + m)
            }
        }
    }
}

import Foundation

/// Feature-level augmentation (D9): rotation simulates re-seating, time-warp simulates speaking
/// rate, scaling simulates effort. Only ever applied to training data.
public struct AugmentConfig: Sendable, Hashable {
    public var maxRotationDegrees: Double = 12
    public var warp: ClosedRange<Double> = 0.85...1.15
    public var amplitude: ClosedRange<Double> = 0.9...1.1
    /// Jitter as a fraction of each channel's spread in this sequence.
    public var jitter: Double = 0.03
    public init() {}
}

public enum Augment {
    public static func augment(_ seq: FeatureSequence, config: AugmentConfig = AugmentConfig(),
                               rng: inout SeededRNG) -> FeatureSequence {
        guard seq.count >= 2, seq.dims % 3 == 0 else { return seq }
        let angle = rng.uniform(-config.maxRotationDegrees, config.maxRotationDegrees) * .pi / 180
        let rotation = Mat3(rotationVector: rng.unitVector() * angle)
        let gain = rng.uniform(config.amplitude.lowerBound, config.amplitude.upperBound)
        let warp = rng.uniform(config.warp.lowerBound, config.warp.upperBound)

        // Rotate each xyz triplet, scale.
        var rotated = seq
        for i in 0..<seq.count {
            for g in stride(from: 0, to: seq.dims, by: 3) {
                let v = rotation * Vec3(seq[frame: i, dim: g], seq[frame: i, dim: g + 1], seq[frame: i, dim: g + 2])
                rotated[frame: i, dim: g] = v.x * gain
                rotated[frame: i, dim: g + 1] = v.y * gain
                rotated[frame: i, dim: g + 2] = v.z * gain
            }
        }

        // Time-warp by linear resampling.
        let newCount = max(4, Int((Double(seq.count) * warp).rounded()))
        var values = [Double](repeating: 0, count: newCount * seq.dims)
        for k in 0..<newCount {
            let pos = Double(k) * Double(seq.count - 1) / Double(newCount - 1)
            let i = min(Int(pos), seq.count - 2), f = pos - Double(i)
            for d in 0..<seq.dims {
                values[k * seq.dims + d] = rotated[frame: i, dim: d] * (1 - f) + rotated[frame: i + 1, dim: d] * f
            }
        }
        var out = FeatureSequence(values: values, dims: seq.dims)

        // Jitter relative to each channel's spread.
        if config.jitter > 0 {
            for d in 0..<seq.dims {
                let ch = out.channel(d)
                let mean = ch.reduce(0, +) / Double(ch.count)
                let sd = (ch.map { pow($0 - mean, 2) }.reduce(0, +) / Double(ch.count)).squareRoot()
                for i in 0..<out.count { out[frame: i, dim: d] += rng.normal() * sd * config.jitter }
            }
        }
        return out
    }
}

import Foundation

/// Label for "not a word" movements: chewing, swallowing, head turns, nods… (D11).
public let noneLabel = "_none"

public struct ClassifierConfig: Sendable, Hashable {
    public var k: Int = 3
    public var augmentCopies: Int = 4
    public var band: Double = 0.2
    public var augment = AugmentConfig()
    public var seed: UInt64 = 1
    public init() {}
}

public struct LabeledFeatures: Sendable {
    public var id: String
    public var label: String
    public var features: FeatureSequence
    public init(id: String, label: String, features: FeatureSequence) {
        self.id = id; self.label = label; self.features = features
    }
}

public struct RankedLabel: Hashable, Sendable, Identifiable {
    public var label: String
    public var score: Double
    public var id: String { label }
}

public struct Prediction: Sendable {
    public var ranked: [RankedLabel]
    /// 1 − best/second-best score.
    public var margin: Double
    public var accepted: Bool
    public var rejectReason: String?
    public var best: RankedLabel? { ranked.first }
}

/// Mean-of-k-nearest DTW classifier over real + augmented references (D10).
public struct Classifier: Sendable {
    struct Reference: Sendable { var label: String; var owner: Int; var sequence: FeatureSequence }

    public let config: ClassifierConfig
    public let labels: [String]
    let scales: [Double]
    let references: [Reference]

    public init?(training: [LabeledFeatures], config: ClassifierConfig = ClassifierConfig()) {
        let usable = training.filter { $0.features.count >= 4 }
        guard Set(usable.map(\.label)).count >= 2 else { return nil }
        self.config = config
        self.labels = Array(Set(usable.map(\.label))).sorted()
        self.scales = Features.channelScales(usable.map(\.features))
        self.references = Self.buildReferences(usable, scales: scales, config: config)
    }

    static func buildReferences(_ takes: [LabeledFeatures], scales: [Double], config: ClassifierConfig) -> [Reference] {
        var refs: [Reference] = []
        for (owner, take) in takes.enumerated() {
            let base = Features.scaled(take.features, by: scales)
            refs.append(Reference(label: take.label, owner: owner, sequence: base))
            var rng = SeededRNG(seed: config.seed ^ stableHash(take.id))
            for _ in 0..<config.augmentCopies {
                refs.append(Reference(label: take.label, owner: owner,
                                      sequence: Augment.augment(base, config: config.augment, rng: &rng)))
            }
        }
        return refs
    }

    /// Classes ranked by mean of the k smallest distances. `active` restricts to a word subset
    /// (context screens); `_none` is always kept.
    public func rank(_ query: FeatureSequence, active: Set<String>? = nil) -> [RankedLabel] {
        let q = Features.scaled(query, by: scales)
        let allowed = active.map { $0.union([noneLabel]) }
        var nearest: [String: [Double]] = [:]
        for ref in references {
            if let allowed, !allowed.contains(ref.label) { continue }
            var list = nearest[ref.label] ?? []
            let cutoff = list.count >= config.k ? list[list.count - 1] : .infinity
            let d = DTW.distance(q, ref.sequence, band: config.band, cutoff: cutoff)
            guard d.isFinite else { nearest[ref.label] = list; continue }
            let at = list.firstIndex { $0 > d } ?? list.count
            list.insert(d, at: at)
            if list.count > config.k { list.removeLast() }
            nearest[ref.label] = list
        }
        return nearest.compactMap { label, ds in
            ds.isEmpty ? nil : RankedLabel(label: label, score: ds.reduce(0, +) / Double(ds.count))
        }.sorted { $0.score < $1.score }
    }

    public func predict(_ query: FeatureSequence, active: Set<String>? = nil,
                        maxScore: Double = .infinity, minMargin: Double = 0) -> Prediction {
        let ranked = rank(query, active: active)
        let margin = Self.margin(ranked)
        var reason: String?
        if let best = ranked.first {
            if best.label == noneLabel { reason = "Looked like non-word movement" }
            else if best.score > maxScore { reason = "Too far from every trained word" }
            else if margin < minMargin { reason = "Too close between \(ranked[0].label) and \(ranked[1].label)" }
        } else {
            reason = "No usable motion"
        }
        return Prediction(ranked: ranked, margin: margin, accepted: reason == nil, rejectReason: reason)
    }

    static func margin(_ ranked: [RankedLabel]) -> Double {
        guard ranked.count >= 2, ranked[1].score > 0 else { return ranked.isEmpty ? 0 : 1 }
        return max(0, 1 - ranked[0].score / ranked[1].score)
    }
}

