func rms(_ x: [Double]) -> Double { (x.map { $0 * $0 }.reduce(0, +) / Double(max(x.count, 1))).squareRoot() }
let signal = rms(fa.values)
let canonicalDiff = rms(zip(fa.values, fb.values).map(-))
