    func start(words: [String], reps: Int, blocks: Int, noisePerBlock: Int, prefix: String = "enroll") {
        guard task == nil, !words.isEmpty else { return }
        let session = Self.stamp()
        totalBlocks = blocks
        total = blocks * (words.count * reps + noisePerBlock)
        completed = 0; rejected = 0; block = 0; log = []
        task = Task { [weak self] in
            await self?.run(words: words, reps: reps, blocks: blocks, noise: noisePerBlock,
                            session: session, prefix: prefix)
            self?.task = nil
        }
    }

    func stop() {
        task?.cancel()
        task = nil
        breakContinuation?.resume()
        breakContinuation = nil
        phase = .idle
    }

    func continueAfterBreak() {
        breakContinuation?.resume()
        breakContinuation = nil
    }

    private func run(words: [String], reps: Int, blocks: Int, noise: Int, session: String, prefix: String) async {
