15	            case .evaluate: "checkmark.seal"
16	            case .decode: "text.bubble"
17	            }
18	        }
19	    }
20	
21	    let hub = MotionHub()
22	    let cues = CueService()
23	    let stem = StemPress()
24	    @ObservationIgnored private(set) lazy var enrollment = Enrollment(model: self)
25	    @ObservationIgnored private(set) lazy var decoder = Decoder(model: self)
26	
27	    var screen: Screen = .enroll
28	    private(set) var dataset: Dataset
29	    private(set) var classifier: Classifier?
30	    private(set) var isTraining = false
31	    private(set) var evaluation: EvaluationReport?
32	    private(set) var isEvaluating = false
33	    private(set) var evaluationProgress = 0.0
34	
35	    @ObservationIgnored let featureConfig = FeatureConfig()
36	    @ObservationIgnored private var featureCache: [UUID: SegmentFeatures] = [:]
