50	        guard !started else { return }
51	        started = true
52	        hub.onSample = { [weak self] s in self?.decoder.ingest(s) }
53	        stem.onPress = { [weak self] in self?.stemPressed() }
54	        if CommandLine.arguments.contains("--smoke") { SmokeTest(model: self).run() }
55	        hub.start()
56	        installKeyMonitor()
57	        rebuildClassifier()
58	    }
59	
60	    var isSimulated: Bool { hub.isSimulated }
61	
62	    func setSource(_ source: MotionHub.Source) {
63	        guard source != hub.source else { return }
64	        enrollment.stop()
65	        hub.source = source
66	        dataset = DatasetStore.load(simulated: source == .simulator)
67	        featureCache.removeAll()
68	        evaluation = nil
69	        rebuildClassifier()
70	    }
