100	        let word = raw.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
101	        guard !word.isEmpty, word != noneLabel, !dataset.vocabulary.contains(word) else { return }
102	        dataset.vocabulary.append(word)
103	        DatasetStore.save(dataset, simulated: isSimulated)
104	    }
105	
106	    func removeWord(_ word: String) {
107	        dataset.vocabulary.removeAll { $0 == word }
108	        DatasetStore.save(dataset, simulated: isSimulated)
109	    }
110	
111	    func takeCount(_ label: String) -> Int { dataset.takes.filter { $0.label == label }.count }
112	    var blocks: [String] { Array(Set(dataset.takes.map(\.block))).sorted() }
113	
114	    private func persist() {
115	        DatasetStore.save(dataset, simulated: isSimulated)
116	        evaluation = nil
117	        rebuildClassifier()
118	    }
119	
120	    // MARK: Training / evaluation
121	
122	    func rebuildClassifier() {
123	        rebuildTask?.cancel()
124	        let training = dataset.takes.compactMap { take in
125	            features(for: take).map { LabeledFeatures(id: take.id.uuidString, label: take.label, features: $0.sequence) }
126	        }
127	        isTraining = true
128	        rebuildTask = Task { [weak self] in
129	            let built = await Task.detached(priority: .userInitiated) { Classifier(training: training) }.value
130	            guard !Task.isCancelled, let self else { return }
131	            self.classifier = built
132	            self.isTraining = false
133	        }
134	    }
135	
136	    func runEvaluation() {
137	        guard !isEvaluating else { return }
138	        let takes = dataset.takes.compactMap { take in
139	            features(for: take).map { EvalTake(id: take.id.uuidString, label: take.label, block: take.block, features: $0.sequence) }
140	        }
141	        isEvaluating = true
142	        evaluationProgress = 0
143	        let box = WeakModel(self)
144	        Task { [weak self] in
145	            let report = await Task.detached(priority: .userInitiated) {
146	                Evaluation.run(takes, permutations: 200) { p in
147	                    Task { @MainActor in box.model?.evaluationProgress = p }
148	                }
149	            }.value
150	            self?.evaluation = report
151	            self?.isEvaluating = false
152	        }
153	    }
154	
155	    // MARK: Input
156	
157	    private func stemPressed() {
158	        if screen == .decode { decoder.trigger() }
159	        else if screen == .enroll { enrollment.continueAfterBreak() }
160	    }
161	
162	    private func installKeyMonitor() {
163	        keyMonitor = NSEvent.addLocalMonitorForEvents(matching: .keyDown) { [weak self] event in
164	            guard let self else { return event }
165	            if NSApp.keyWindow?.firstResponder is NSText { return event }
166	            let consumed: Bool = MainActor.assumeIsolated {
167	                switch (event.keyCode, self.screen) {
168	                case (49, .decode): if !event.isARepeat { self.decoder.trigger() }; return true          // Space
169	                case (49, .enroll): self.enrollment.continueAfterBreak(); return true
170	                case (16, .decode): self.decoder.confirm(true); return true                               // Y
171	                case (45, .decode): self.decoder.confirm(false); return true                              // N
172	                default: return false
173	                }
174	            }
175	            return consumed ? nil : event
176	        }
177	    }
178	}
179	
180	/// Lets a background progress callback reach the main-actor model without capturing it.
181	private final class WeakModel: @unchecked Sendable {
182	    weak var model: AppModel?
183	    init(_ model: AppModel) { self.model = model }
184	}
