                let delay = features.trailingSeconds + Date().timeIntervalSince(captureEnd)
                if let i = self.results.firstIndex(where: { $0.id == result.id }) {
                    self.results[i].voiceDelay = delay
                    self.results[i].voiceSource = spoken.source
                }
